/* ---- drawing helpers for this lesson (prefixed OF_ so nothing clashes with the engine) ---- */
const OF_F='font-family="Nunito Sans, sans-serif"';
const OF_T=(x,y,t,o={})=>`<text x="${(+x).toFixed(1)}" y="${(+y).toFixed(1)}" ${OF_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.ex?' '+o.ex:''}>${t}</text>`;
const OF_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${(+x1).toFixed(1)}" y1="${(+y1).toFixed(1)}" x2="${(+x2).toFixed(1)}" y2="${(+y2).toFixed(1)}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const OF_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"${o.ex?' '+o.ex:''}/>`;
const OF_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return OF_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2.toFixed(1)},${y2.toFixed(1)} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const OF_R=d=>d*Math.PI/180;
const OF_GREY='#5C6577', OF_CORE='#DBE4FF', OF_CLAD='#F1F3F5';
/* the book's numbers, computed once */
const OF_TC=Math.asin(1.45/1.50)*180/Math.PI;                 // 75.16°
const OF_NA=Math.sqrt(1.50*1.50-1.45*1.45);                  // 0.3841
const OF_TA=Math.asin(OF_NA)*180/Math.PI;                    // 22.59°
const OF_TR=Math.asin(OF_NA/1.50)*180/Math.PI;               // 14.84°
const OF_mW=dbm=>Math.pow(10,dbm/10);                        // dBm -> mW
/* a boundary with a normal and one ray at angle th (deg, from the normal) arriving from the core below */
const OF_snell=(px,py,th,L,kind,col)=>{const s=Math.sin(OF_R(th)),co=Math.cos(OF_R(th));let o=OF_L(px,py-80,px,py+80,OF_GREY,2,'stroke-dasharray="6 6"');
 o+=OF_arrow(px-L*s,py+L*co,px-2,py-1,col,4);
 if(kind==='refr'){const t2=Math.asin(1.50*s/1.45);o+=OF_arrow(px,py,px+L*Math.sin(t2),py-L*Math.cos(t2),col,4)}
 else if(kind==='graze'){o+=OF_arrow(px,py-2,px+L,py-2,col,4)}
 else {o+=OF_arrow(px,py,px+L*s,py+L*co,col,4)}
 return o};
/* a fiber drawn side-on: end face at x0, core between yc-hc and yc+hc, cladding of width cw on each side, to x1 */
const OF_fiber=(x0,x1,yc,hc,cw)=>`<rect x="${x0}" y="${yc-hc-cw}" width="${x1-x0}" height="${cw}" fill="${OF_CLAD}" stroke="#ADB5BD" stroke-width="2"/><rect x="${x0}" y="${yc+hc}" width="${x1-x0}" height="${cw}" fill="${OF_CLAD}" stroke="#ADB5BD" stroke-width="2"/><rect x="${x0}" y="${yc-hc}" width="${x1-x0}" height="${2*hc}" fill="${OF_CORE}" stroke="${BLU}" stroke-width="2"/>`+OF_L(x0,yc-hc-cw,x0,yc+hc+cw,'#18213A',4);
/* a ray guided down a fiber: enters the end face at (x0,yc) at inside angle tr, bounces between the walls until x1 */
const OF_zig=(x0,x1,yc,hc,tr,col,w=4)=>{let p=[[x0,yc]],x=x0,y=yc,dir=-1,t=Math.tan(OF_R(tr));for(let k=0;k<40&&x<x1;k++){const yw=yc+dir*hc,dx=Math.abs(yw-y)/t;if(x+dx>=x1){p.push([x1,y+dir*(x1-x)*t]);x=x1;break}x+=dx;y=yw;p.push([x,y]);dir=-dir}
 return `<polyline points="${p.map(q=>q[0].toFixed(1)+','+q[1].toFixed(1)).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round"/>`};
/* the dB power line of the worked example: 0 dBm at 0 km falling 0.2 dB/km to -4 dBm at 20 km */
const OF_dbline=(x0,x1,y0,ky,col)=>OF_L(x0,y0,x1,y0+ky*0.2*20,col,5);

